window.ScripturaLexicons = window.ScripturaLexicons || {};
window.ScripturaLexicons.BDAG_PART_0020 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alektorophonia-bdag\" data-source=\"BDAG\" data-search=\"ἀλεκτοροφωνία alektorophonia canto do galo madrugada terceira vigília BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλεκτοροφωνία</td><td>Substantivo</td><td>canto do galo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alektryon-bdag\" data-source=\"BDAG\" data-search=\"ἀλεκτρυών alektryon galo frango macho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλεκτρυών</td><td>Substantivo</td><td>galo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alektor-bdag\" data-source=\"BDAG\" data-search=\"ἀλέκτωρ alektor galo canta canto do galo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλέκτωρ</td><td>Substantivo</td><td>galo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alexandreus-bdag\" data-source=\"BDAG\" data-search=\"ἀλεξανδρεύς Alexandreus alexandrino Apolo sinagoga Alexandria BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλεξανδρεύς</td><td>Substantivo</td><td>alexandrino</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alexandrinos-bdag\" data-source=\"BDAG\" data-search=\"ἀλεξανδρῖνος Alexandrinos alexandrino navio Alexandria BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλεξανδρῖνος</td><td>Adjetivo</td><td>alexandrino</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alexandros-bdag\" data-source=\"BDAG\" data-search=\"Ἀλέξανδρος Alexandros Alexandre nome próprio Simão Cirene sumo sacerdote Éfeso apóstata latoeiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀλέξανδρος</td><td>Nome próprio</td><td>Alexandre</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alesmos-bdag\" data-source=\"BDAG\" data-search=\"ἀλεσμός alesmos trituração moenda tortura martírio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλεσμός</td><td>Substantivo</td><td>trituração; tortura</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aleuron-bdag\" data-source=\"BDAG\" data-search=\"ἄλευρον aleuron farinha trigo pão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄλευρον</td><td>Substantivo</td><td>farinha de trigo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aletheia-bdag\" data-source=\"BDAG\" data-search=\"ἀλήθεια aletheia verdade veracidade fidelidade retidão realidade cristianismo evangelho João BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλήθεια</td><td>Substantivo</td><td>veracidade; verdade; realidade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aletheuo-bdag\" data-source=\"BDAG\" data-search=\"ἀληθεύω aletheuo ser verdadeiro dizer verdade falar verdade amor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀληθεύω</td><td>Verbo</td><td>ser verdadeiro; dizer a verdade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alethes-bdag\" data-source=\"BDAG\" data-search=\"ἀληθής alethes verdadeiro veraz honesto justo real genuíno BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀληθής</td><td>Adjetivo</td><td>verdadeiro; veraz; real</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-alektorophonia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλεκτοροφωνία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦alektorophōnía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Estrabão 7, 35; Esopo, <em>Fab.</em> 55 P. [diferentemente 110 H.]; Phryn. 229 Lob.; B-D-F §123, 1; Mlt-H. 271.) <strong>Canto do galo.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλεκτοροφωνίας\" data-meanings=\"ao canto do galo; de madrugada\">ἀλεκτοροφωνίας</span>, <strong>ao canto do galo (= madrugada)</strong>, nome da terceira vigília da noite (0–3 h), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26.34</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.75\" target=\"_blank\" rel=\"noopener noreferrer\">26.75</a> v.l. (sobre essas variantes, veja P. Katz, TLZ 80, 1955, 737; G. Zuntz, <em>Chronique d’Égypte</em> 26, 1951, 205s.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13.35</a> (sobre o genitivo, veja B-D-F §186, 2; Rob. 471). — Sobre galinhas na Judeia e em Jerusalém, veja K. Rengstorf sobre <em>Tosefta Yebamoth</em> 3, 4 (Rabb. Texte I 3, 1933, p. 36s.). — Dalman, <em>Arbeit</em> VII (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἰκία\" data-meanings=\"casa\">οἰκία</span> 1a); T. Martin, <em>Biblical Research</em> 38, 1893, 59–69.\n</p></section></article><article id=\"entry-alektryon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλεκτρυών</h1><div class=\"entry-meta\"><span class=\"greek\">όνος, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦alektruṓn⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Frango macho, galo</strong> (sobre a formação, veja DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλέξω\" data-meanings=\"afastar; defender\">ἀλέξω</span>, <em>Thème</em> II p. 50; desde Teógnis 864; Cratino 108, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κοκκύζει\" data-meanings=\"canta como galo\">κοκκύζει</span> 311; POxy 1207, 8; Michel 692, 5 [I d.C.]; SIG 1173, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">3 Mac 5.23</a>; PGM 3, 693; 701), Fragmento Evangélico do Fayum (Kl. T. 83, p. 23, 10; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.26–31</a> e paralelos). — B. 174.\n</p></section></article><article id=\"entry-alektor-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλέκτωρ</h1><div class=\"entry-meta\"><span class=\"greek\">ορος, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aléktōr⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Galo</strong>, como no verbete precedente (para a época clássica, veja W. Rutherford, <em>New Phryn.</em>, 1881, 307; Licofron 1094; Batr. 192; papiros, por exemplo PTebt 140 [72 a.C.]; PFay 119, 29 [c. 100 d.C.]; BGU 269, 4; 1067, 11; PGM 2, 73; 4, 2190; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.30.31\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 30.31</a>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φωνεῖ\" data-meanings=\"canta; emite o canto\">φωνεῖ</span> (GrBar), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26.34</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.74\" target=\"_blank\" rel=\"noopener noreferrer\">74s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.30</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.68\" target=\"_blank\" rel=\"noopener noreferrer\">68</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.72\" target=\"_blank\" rel=\"noopener noreferrer\">72</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.34</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.60\" target=\"_blank\" rel=\"noopener noreferrer\">60s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.38\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.27\" target=\"_blank\" rel=\"noopener noreferrer\">18.27</a>. — M-M.\n</p></section></article><article id=\"entry-alexandreus-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλεξανδρεύς</h1><div class=\"entry-meta\"><span class=\"greek\">έως, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Alexandreús⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Alexandrino</strong> (Plutarco, <em>Pomp.</em> 645 [49, 6]; SEG XXXVIII, 219, 2; OGI índice II; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">3 Mac 2.30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">3.21</a>; Fílon, Josefo, SibOr; veja Preis. III 264 s.v.), de Apolo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 18.24</a> (sobre judeus como <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλεξανδρεύς\" data-meanings=\"alexandrino\">ἀ.</span>, veja Jos., <em>C. Ap.</em> 2, 38, como em papiros CPJ I p. 4). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"συναγωγὴ Ἀ.\" data-meanings=\"sinagoga dos alexandrinos\">συναγωγὴ Ἀ.</span>, <strong>sinagoga dos alexandrinos</strong> (Schürer II 76; 428, 445; III 92–94; 127–129), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 6.9</a>.\n</p></section></article><article id=\"entry-alexandrinos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλεξανδρῖνος</h1><div class=\"entry-meta\"><span class=\"greek\">η, ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Alexandrînos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(As edições têm <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"-ινός\" data-meanings=\"acentuação editorial alternativa\">-ινός</span>; sobre o acento, veja Kühner-Bl. II 296; Mlt-H. 359. — Políbio 34, 8, 7; BGU 142, 5; 143, 3; 741, 4 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κλάση Ἀλεξανδρίνη\" data-meanings=\"frota alexandrina\">κλάση Ἀλεξανδρίνη</span> = lat. <em lang=\"la\">classis Alexandrina</em>; veja Mitt-Wilck. I/1, 379; Preis. III 264 s.v.) <strong>Alexandrino.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πλοῖον Ἀ.\" data-meanings=\"navio alexandrino\">πλοῖον Ἀ.</span>, <strong>navio alexandrino</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 27.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.11\" target=\"_blank\" rel=\"noopener noreferrer\">28.11</a>. Como substantivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">6.9</a> v.l.; veja N25.\n</p></section></article><article id=\"entry-alexandros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀλέξανδρος</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Aléxandros⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><strong>Alexandre</strong>, nome muito usado tanto entre judeus como entre gentios (sobre a origem do nome, veja DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνήρ\" data-meanings=\"homem\">ἀνήρ</span>, p. 88; compare papiros e inscrições; CPJ I 29; Josefo. — ET 10, 1899, 527). <span class=\"sense-number\">1.</span> Filho de Simão de Cirene, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15.21</a>. <span class=\"sense-number\">2.</span> Membro da família sumo-sacerdotal de Jerusalém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 4.6</a>. <span class=\"sense-number\">3.</span> Judeu de Éfeso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.33\" target=\"_blank\" rel=\"noopener noreferrer\">19.33</a>. <span class=\"sense-number\">4.</span> Um apóstata, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1.20</a>, presumivelmente o latoeiro de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 4.14</a>.</p>\n</section></article><article id=\"entry-alesmos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλεσμός</h1><div class=\"entry-meta\"><span class=\"greek\">οῦ, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦alesmós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(De <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλέω\" data-meanings=\"moer\">ἀλέω</span>, “moer”.) Literalmente, <strong>trituração, moagem</strong> (Jos., <em>Ant.</em> 3, 252 v.l.; veja DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλέω\" data-meanings=\"moer\">ἀλέω</span>); em nossa literatura, somente figuradamente com referência à tortura: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλεσμοὶ ὅλου τοῦ σώματος\" data-meanings=\"trituração de todo o corpo\">ἀλεσμοὶ ὅλου τοῦ σώματος</span>, <strong>trituração de todo o corpo</strong> (veja 4:1), da tortura no martírio, IRo 5:3 (veja Lghtf. ad loc. — De uma modalidade particular de tortura, Eunápio, <em>Vi. Soph.</em> 59 cod.; compare 312).</p>\n</section></article><article id=\"entry-aleuron-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄλευρον</h1><div class=\"entry-meta\"><span class=\"greek\">ου, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦áleuron⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Heródoto e outros; PGM 7, 539 e em outros lugares nos papiros; LXX; Jos., <em>Ant.</em> 3, 142; 8, 322; SibOr 8, 14; DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλέω\" data-meanings=\"moer\">ἀλέω</span>.) <strong>Farinha de trigo</strong>, usada para fazer pão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.21</a>. — B. 361. M-M.</p>\n</section></article><article id=\"entry-aletheia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλήθεια</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦alḗtheia⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λανθάνω\" data-meanings=\"passar despercebido; escapar à percepção\">λανθάνω</span>, “escapar à percepção”; veja DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λανθάνω\" data-meanings=\"passar despercebido; escapar à percepção\">λανθάνω</span>; Schwyzer I 469; Homero+.) Sentido primário: “não ocultar nada”.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>A qualidade de estar de acordo com o que é verdadeiro: veracidade, confiabilidade, retidão</strong> no pensamento e na ação (Alceu 57 [366 L.-P.]; Mimnermo 8 e outros). De Deus (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.24.27\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 24.27</a> e outros): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">15.8</a>. De pessoas (Pítaco em Diógenes Laércio 1, 78; Arriano, <em>Anab.</em> 7, 30, 3; Luciano, <em>Dial. Mort.</em> 11, 6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2KI.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">4 Km 20.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDG.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jz 9.15s.</a> e outros; EpArist 206): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ἀληθείᾳ λαλεῖν\" data-meanings=\"falar verazmente\">ἐν ἀ. λαλεῖν</span>, <strong>falar verazmente</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 7.14</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰλικρίνεια\" data-meanings=\"sinceridade; pureza\">εἰλικρίνεια</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 5.8</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαθωσύνη\" data-meanings=\"bondade\">ἀγαθωσύνη</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δικαιοσύνη\" data-meanings=\"justiça; retidão\">δικαιοσύνη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5.9</a>; 1 Cl 19:1; 31:2; 35:2; Pol 2:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν πάσῃ ἀληθείᾳ\" data-meanings=\"com perfeita fidelidade\">ἐν πάσῃ ἀ.</span>, <strong>com perfeita fidelidade</strong>, Pol 4:2. — Hm 8:9; 12, 3, 1; Hs 9, 15, 2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>O conteúdo daquilo que é verdadeiro, verdade</strong>, em oposição a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ψεῦδος\" data-meanings=\"falsidade; mentira\">ψεῦδος</span>. <strong>a.</strong> Em geral: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθειαν λαλεῖν\" data-meanings=\"dizer a verdade\">ἀ. λαλεῖν</span>, <strong>dizer a verdade</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ZEC.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Zc 8.16</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.25</a>; Hm 3:5; 2 Cl 12:3. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθειαν λέγειν\" data-meanings=\"dizer a verdade\">ἀ. λέγειν</span> (Heródoto 2, 115 e outros; PGiss 84, 14 [séc. II d.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν ἀλήθειαν εἰπεῖν\" data-meanings=\"dizer a verdade\">τὴν ἀ. εἰπεῖν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 2.7</a>. Fut. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθειαν ἐρῶ\" data-meanings=\"direi a verdade\">ἀ. ἐρῶ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12.6</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθειαν ἀγαπᾶν\" data-meanings=\"amar a verdade\">ἀ. ἀγαπᾶν</span>, Hm 3:1. Em oposição, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ψεύδεσθαι κατὰ τῆς ἀληθείας\" data-meanings=\"mentir contra a verdade\">ψεύδεσθαι κατὰ τῆς ἀ.</span>, <strong>mentir contra a verdade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3.14</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἶπεν αὐτῷ πᾶσαν τὴν ἀλήθειαν\" data-meanings=\"ela lhe disse toda a verdade\">εἶπεν αὐτῷ πᾶσαν τὴν ἀ.</span>, <strong>ela lhe disse toda a verdade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.33</a> (compare Heródoto 9, 89; Tucídides 6, 87, 1 e outros; Cleopatra l. 88; POxy 283, 13s. [45 d.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γνωσθῆναι πᾶσαν τὴν ἀλήθειαν\" data-meanings=\"ser conhecida toda a verdade\">γνωσθῆναι πᾶσαν τὴν ἀ.</span>; Jos., <em>Bell.</em> 7, 31 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πυθόμενος παρ’ αὐτοῦ πᾶσαν τὴν ἀλήθειαν\" data-meanings=\"tendo sabido dele toda a verdade\">πυθόμενος παρ’ αὐτοῦ πᾶσαν τὴν ἀ.</span>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν λόγῳ ἀληθείας\" data-meanings=\"por palavra veraz\">ἐν λόγῳ ἀληθείας</span>, <strong>por palavra veraz</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6.7</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ῥήματα ἀληθείας\" data-meanings=\"palavras de verdade\">ῥήματα ἀληθείας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 26.25</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μόρφωσις τῆς γνώσεως καὶ τῆς ἀληθείας\" data-meanings=\"expressão concreta do conhecimento e da verdade\">μόρφωσις τῆς γνώσεως καὶ τῆς ἀ.</span>, <strong>expressão concreta do conhecimento e da verdade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2.20</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ ἁγνότης τῆς ἀληθείας\" data-meanings=\"a pureza própria da verdade\">ἡ ἁγνότης τῆς ἀ.</span>, <strong>a pureza própria da verdade</strong>, Hv 3, 7, 3. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔξωθεν τῆς ἀληθείας\" data-meanings=\"fora da verdade; falso\">ἔξωθεν τῆς ἀ.</span> = <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ψευδής\" data-meanings=\"falso\">ψευδής</span>, Hv 3, 4, 3.</p>\n<p class=\"entry-text\"><strong>b.</strong> Especialmente, <strong>o conteúdo do cristianismo como a verdade última</strong> (compare Plutarco, <em>Mor.</em> 351e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθεια περὶ θεῶν\" data-meanings=\"verdade acerca dos deuses\">ἀ. περὶ θεῶν</span>; Fílon, <em>Spec. Leg.</em> 4, 178, o prosélito é <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μεταναστὰς εἰς ἀλήθειαν\" data-meanings=\"emigrante para a verdade\">μεταναστὰς εἰς ἀ.</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.21</a> (C. Scott, Exp. 8ª sér. 3, 1912, 178–185; F. Briggs, ET 39, 1928, 526). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ λόγος τῆς ἀληθείας\" data-meanings=\"a palavra da verdade\">ὁ λόγος τῆς ἀ.</span>, <strong>a palavra da verdade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1.18</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ λόγος τῆς ἀληθείας τοῦ εὐαγγελίου τοῦ παρόντος εἰς ὑμᾶς\" data-meanings=\"a palavra da verdade do evangelho que chegou até vós\">ὁ λόγος τῆς ἀ. τοῦ εὐαγγελίου τοῦ παρόντος εἰς ὑμᾶς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.5</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1.12</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ ἀλήθεια τοῦ εὐαγγελίου\" data-meanings=\"a verdade do evangelho\">ἡ ἀ. τοῦ εὐαγγελίου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2.5</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">14</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔστιν ἀλήθεια Χριστοῦ ἐν ἐμοί\" data-meanings=\"há verdade de Cristo em mim\">ἔστιν ἀ. Χριστοῦ ἐν ἐμοί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11.10</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ περὶ ἀληθείας λόγος\" data-meanings=\"a palavra acerca da verdade\">ὁ περὶ ἀ. λόγος</span>, Pol 3:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πείθεσθαι τῇ ἀληθείᾳ\" data-meanings=\"obedecer à verdade\">πείθεσθαι τῇ ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5.7</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πιστεύειν τῇ ἀληθείᾳ\" data-meanings=\"crer na verdade\">πιστεύειν τῇ ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2.12</a>; daí <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πίστει ἀληθείας\" data-meanings=\"fé na verdade\">πίστει ἀληθείας</span>, <strong>fé na verdade</strong>, v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δύνασθαί τι κατὰ τῆς ἀληθείας … ὑπὲρ τῆς ἀληθείας\" data-meanings=\"poder algo contra a verdade … em favor da verdade\">δύνασθαί τι κατὰ τῆς ἀ. … ὑπὲρ τῆς ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 13.8</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"περιπατεῖν ἐν ἀληθείᾳ\" data-meanings=\"andar na verdade\">περιπατεῖν ἐν ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2JN.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Jo 4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">3Jo 3s.</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2KI.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">4 Km 20.3</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ζῆν κατὰ ἀλήθειαν\" data-meanings=\"viver segundo a verdade\">ζῆν κατὰ ἀ.</span>, IEph 6:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πορεύεσθαι κατὰ τὴν ἀλήθειαν\" data-meanings=\"andar segundo a verdade\">πορεύεσθαι κατὰ τὴν ἀ.</span>, Pol 5:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ἀληθείᾳ\" data-meanings=\"na verdade\">ἐν ἀ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1KI.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">3 Km 2.4</a>), Hm 3:4; cingir-se com a verdade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6.14</a>; compare Hm 11:4.</p>\n<p class=\"entry-text\">A verdade se expressa em virtudes como justiça e santidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.24</a> (Nicol. Dam.: 90 Fgm. 67, 1 Jac. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δικαιοσύνην καὶ ἀλήθειαν\" data-meanings=\"justiça e verdade\">δικαιοσύνην κ. ἀλ.</span>). Por isso, contrasta com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδικία\" data-meanings=\"injustiça\">ἀδικία</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 13.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2.8</a>. Nesta última passagem, uma atitude negativa em relação à verdade é chamada <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπειθεῖν τῇ ἀληθείᾳ\" data-meanings=\"desobedecer à verdade\">ἀπειθεῖν τῇ ἀ.</span>. Também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πλανᾶσθαι ἀπὸ τῆς ἀληθείας\" data-meanings=\"desviar-se da verdade\">πλανᾶσθαι ἀπὸ τῆς ἀ.</span>, <strong>desviar-se da verdade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5.19</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀστοχεῖν περὶ τὴν ἀλήθειαν\" data-meanings=\"errar quanto à verdade\">ἀστοχεῖν περὶ τὴν ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2.18</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καταστρέφειν ἀπὸ τῆς ἀληθείας\" data-meanings=\"desviar da verdade\">καταστρέφειν ἀπὸ τῆς ἀ.</span>, Hs 6, 2, 1, compare 4; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀποστρέφειν τὴν ἀκοὴν ἀπὸ τῆς ἀληθείας\" data-meanings=\"desviar o ouvido da verdade\">ἀποστρέφειν τὴν ἀκοὴν ἀπὸ τῆς ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 4.4</a>, em oposição a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μῦθοι\" data-meanings=\"mitos; fábulas\">μῦθοι</span>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀποστρέφεσθαι\" data-meanings=\"afastar-se\">ἀποστρέφεσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1.14</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀποστερεῖσθαι τῆς ἀληθείας\" data-meanings=\"estar privado da verdade\">ἀποστερεῖσθαι τῆς ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6.5</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐρευνᾶν περὶ τῆς ἀληθείας\" data-meanings=\"investigar acerca da verdade\">ἐρευνᾶν περὶ τῆς ἀ.</span>, Hm 10, 1, 4; 6; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνθίστασθαι τῇ ἀληθείᾳ\" data-meanings=\"opor-se à verdade\">ἀνθίστασθαι τῇ ἀ.</span>, <strong>opor-se à verdade</strong> (isto é, ao evangelho), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3.8</a>. Em oposição a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μῦθοι\" data-meanings=\"mitos; fábulas\">μῦθοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">4.4</a>.</p>\n<p class=\"entry-text\">A verdade pode ser comunicada (compare Dídimo, <em>Gen.</em> 86, 21): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φανερώσει τῆς ἀληθείας\" data-meanings=\"pela manifestação clara da verdade\">φανερώσει τῆς ἀ.</span>, <strong>pela manifestação clara da verdade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4.2</a> (semelhantemente em oração cristã posterior, POxy 925, 4s. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φανέρωσόν μοι τὴν παρὰ σοὶ ἀλήθειαν\" data-meanings=\"manifesta-me a verdade que está contigo\">φανέρωσόν μοι τὴν παρὰ σοὶ ἀλ.</span>); é ensinada, D 11:10; reconhecida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 4.3</a>; Hv 3, 6, 2; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπίγνωσις τῆς ἀληθείας\" data-meanings=\"conhecimento da verdade\">ἐπίγνωσις τῆς ἀληθείας</span> (Alex. Aphr., <em>Quaest.</em> 3, 12, II 2 p. 102, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γνῶσις τῆς ἀληθείας\" data-meanings=\"conhecimento da verdade\">γνῶσις τ. ἀληθείας</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 2.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">3.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10.26</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἑδραίωμα τῆς ἀληθείας\" data-meanings=\"fundamento da verdade\">ἑδραίωμα τῆς ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 3.15</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁδὸς τῆς ἀληθείας\" data-meanings=\"caminho da verdade\">ὁδὸς τῆς ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2.2</a>; 1 Cl 35:5 (compare Píndaro, <em>P.</em> 3, 103; Eurípides, Fgm. 289; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.24.48\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 24.48</a> e outros; En 104:13; OdeSol 11:3); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὑπακοὴ τῆς ἀληθείας\" data-meanings=\"obediência à verdade\">ὑπακοὴ τῆς ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1.22</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάπη τῆς ἀληθείας\" data-meanings=\"amor da verdade\">ἀγάπη τῆς ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2.10</a>. Deus é <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πατὴρ τῆς ἀληθείας\" data-meanings=\"Pai da verdade\">πατὴρ τῆς ἀ.</span>, 2 Cl 3:1; 20:5; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φῶς ἀληθείας\" data-meanings=\"luz da verdade\">φῶς ἀληθείας</span>, IPhld 2:1 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.42.3\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 42.3</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θεὸς τῆς ἀληθείας\" data-meanings=\"Deus da verdade\">θεὸς τῆς ἀ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1ES.4.40\" target=\"_blank\" rel=\"noopener noreferrer\">1Esd 4.40</a>), 2 Cl 19:1; compare 1 Cl 60:2. A construção genitiva inversa em <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθεια τοῦ θεοῦ\" data-meanings=\"verdade acerca de Deus\">ἀ. τοῦ θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.25</a>, é melhor traduzida por <strong>verdade acerca de Deus</strong> (assim Twentieth Century NT, NRSV), em oposição ao engano dos politeístas, que na prática mentem acerca de Deus apesar do melhor conhecimento descrito nos vv. 19–21 (REB e outros: “verdade de Deus”).</p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθεια\" data-meanings=\"verdade\">Ἀ.</span> é palavra favorita da literatura joanina e nela desempenha papel importante. A palavra de Deus é verdade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.17\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 17.17</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.118.142\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 118.142</a>). Verdade com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"χάρις\" data-meanings=\"graça\">χάρις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.14</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">17</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πνεῦμα\" data-meanings=\"espírito\">πνεῦμα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">4.23s.</a>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ἔργῳ καὶ ἀληθείᾳ\" data-meanings=\"em ação e em verdade\">ἐν ἔργῳ καὶ ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3.18</a>, em oposição a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λόγῳ, γλώσσῃ\" data-meanings=\"em palavra, em língua\">λόγῳ, γλώσσῃ</span>. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάπη\" data-meanings=\"amor\">ἀγάπη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2JN.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Jo 3</a>. O Espírito conduz à verdade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16.13</a>; daí <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πνεῦμα τῆς ἀληθείας\" data-meanings=\"Espírito da verdade\">πνεῦμα τῆς ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">14.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">15.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">16.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 4.6</a> (compare Hm 3:4). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πνεῦμα\" data-meanings=\"Espírito\">πνεῦμα</span> é identificado com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθεια\" data-meanings=\"verdade\">ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5.6</a>; ela é mediada por Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.17</a>, que chama a si mesmo de verdade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">14.6</a> (compare PGM 5, 148 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐγώ εἰμι ἡ ἀλήθεια\" data-meanings=\"eu sou a verdade\">ἐγώ εἰμι ἡ ἀλήθεια</span>; em contraste, POxy 1380, 63 [início do séc. II d.C.] chama Ísis de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθεια\" data-meanings=\"verdade\">ἀ.</span>; Apolo, Berl. Gr. Pap. 11517 [séc. II d.C.]: <em>Hermes</em> 55, 1920, 188–195, l. 52, é <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀψευδὴς ἀλήθεια\" data-meanings=\"verdade que não mente\">ἀψευδὴς ἀ.</span>; Marco Aurélio 9, 1, 2: Deus = Natureza é chamado <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθεια\" data-meanings=\"verdade\">ἀλήθεια</span>; Luciano, <em>Hist. Conscr.</em> 61, diz de um bom historiador <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἦν ἀλήθεια ἐπὶ πᾶσι\" data-meanings=\"havia verdade em tudo\">ἦν ἀλήθεια ἐπὶ πᾶσι</span>); daí, como fonte de louvor para um cristão, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Δημητρίῳ μεμαρτύρηται … ὑπ’ αὐτῆς τῆς ἀληθείας\" data-meanings=\"a Demétrio foi dado testemunho pela própria verdade\">Δημητρίῳ μεμαρτύρηται … ὑπ’ αὐτῆς τῆς ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">3Jo 12</a>.</p>\n<p class=\"entry-text\">Quem possui Cristo conhece a verdade (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γινώσκειν τὴν ἀλήθειαν\" data-meanings=\"conhecer a verdade\">γινώσκ. τὴν ἀ.</span>, como Jos., <em>Ant.</em> 13, 291; Taciano 13, 1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθείας γνῶσις\" data-meanings=\"conhecimento da verdade\">ἀληθείας γνῶσις</span>: Máximo de Tiro 26, 5b; Dídimo, <em>Gen.</em> 116, 17), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.32</a> (compare 1QS 5:10); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2JN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Jo 1</a>; pratica a verdade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3.21</a>, compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 1.6</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ποιεῖν τὴν ἀλήθειαν\" data-meanings=\"praticar a verdade\">ποιεῖν τὴν ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.32.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 32.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.47.29\" target=\"_blank\" rel=\"noopener noreferrer\">47.29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.26.10\" target=\"_blank\" rel=\"noopener noreferrer\">Is 26.10</a> e outros; TestReub 6:9; TestBenj 10:3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔλεος καὶ ἀλήθεια\" data-meanings=\"misericórdia e verdade\">ἔλεος καὶ ἀ.</span>, PsSol 17:15); permanece na verdade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.44</a>; é da verdade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.37\" target=\"_blank\" rel=\"noopener noreferrer\">18.37</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">3.19</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκ τῆς ἀληθείας\" data-meanings=\"de acordo com a verdade\">ἐκ τῆς ἀληθείας</span> = <strong>de acordo com a verdade</strong>, PTurin I, 6, 13). A verdade liberta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.32</a>, mas não está presente nos que negam o fato do pecado em suas vidas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 1.8</a>, nem nos que deixam de obedecer aos mandamentos de Cristo. Cristo proclama essa verdade: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λέγειν\" data-meanings=\"dizer\">λέγειν</span> (Jos., <em>Ant.</em> 10, 124), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.45\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.45s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">16.7</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λαλεῖν\" data-meanings=\"falar\">λαλεῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.40\" target=\"_blank\" rel=\"noopener noreferrer\">8.40</a> (também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λαλεῖν ἐν ἀληθείᾳ\" data-meanings=\"falar na verdade\">λαλεῖν ἐν ἀ.</span>, IEph 6:2); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μαρτυρεῖν τῇ ἀληθείᾳ\" data-meanings=\"dar testemunho à verdade\">μαρτυρεῖν τῇ ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.37\" target=\"_blank\" rel=\"noopener noreferrer\">18.37</a>. Assim como João Batista dá testemunho de Jesus, ele dá testemunho da verdade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">5.33</a>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μαρτυρούντων σου τῇ ἀληθείᾳ\" data-meanings=\"dando testemunho de tua fidelidade à verdade\">μαρτυρούντων σου τῇ ἀληθείᾳ</span>, <strong>dando testemunho de tua fidelidade à verdade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">3Jo 3</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα συνεργοὶ γινώμεθα τῇ ἀληθείᾳ\" data-meanings=\"para que nos tornemos cooperadores da verdade\">ἵνα συνεργοὶ γινώμεθα τῇ ἀ.</span>, v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">8</a>. Na pergunta de Pilatos <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τί ἐστιν ἀλήθεια;\" data-meanings=\"que é a verdade?\">τί ἐστιν ἀ.;</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.38\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18.38</a>, fala o homem do mundo (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">4Mac 5.10</a>). Em oposição a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θάνατος\" data-meanings=\"morte\">θάνατος</span>, ISm 5:1. — Mlt-Turner 177s.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Um acontecimento ou estado efetivo, realidade</strong> (Diógenes 21 p. 114, 10 e outros, Malherbe; Mel., <em>P.</em> 4, 33; 42, 289, em oposição a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τύπος\" data-meanings=\"tipo; figura\">τύπος</span>; Diod S 2, 8, 4), em contraste com mera aparência (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πρόφασις\" data-meanings=\"pretexto; aparência\">πρόφασις</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.18</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κατὰ ἀλήθειαν\" data-meanings=\"corretamente; segundo a verdade\">κατὰ ἀλήθειαν</span>, <strong>corretamente</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2.2</a> (compare Diod S 4, 64, 2 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ κατ’ ἀλήθειαν γονεῖς\" data-meanings=\"os pais verdadeiros\">οἱ κατ’ ἀλήθειαν γονεῖς</span>; Marco Aurélio 2, 11, 3; 4, 11; Damiano de Larissa p. 20, 2 [ed. Schöne 1897]; PCairZen 202, 7 [254 a.C.]; EpArist 140; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">4Mac 5.18</a>; Just., <em>A I</em> 2, 1; Atenágoras, <em>R.</em> 66, 11; Orígenes, <em>C. Cels.</em> 2, 13, 84; PGM 12, 235). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ἀληθείᾳ\" data-meanings=\"de fato; verdadeiramente\">ἐν ἀληθείᾳ</span>, <strong>de fato, verdadeiramente</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.33.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 33.15</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαπᾶν\" data-meanings=\"amar\">ἀγαπᾶν</span>, PsSol 6:6; 10:3; 14:1 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 17.19</a>; 1 Cl 63:1 (veja também 2b sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3.18</a>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπιγινώσκειν τὴν χάριν ἐν ἀληθείᾳ\" data-meanings=\"reconhecer a graça em verdade\">ἐπιγινώσκειν τὴν χάριν ἐν ἀλ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.6</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὓς ἐγὼ ἀγαπῶ ἐν ἀληθείᾳ\" data-meanings=\"a quem eu amo verdadeiramente\">οὓς ἐγὼ ἀγαπῶ ἐν ἀλ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2JN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Jo 1</a>, compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">3Jo 1</a>, pertence aqui (como nas fórmulas epistolares PFay 118, 26; 119, 26 [100–110 d.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοὺς φιλοῦντας ἡμᾶς πρὸς ἀλήθειαν\" data-meanings=\"os que realmente e verdadeiramente nos amam\">τοὺς φιλοῦντας ἡμᾶς πρὸς ἀ.</span> = “real e verdadeiramente”). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπ’ ἀληθείας\" data-meanings=\"de acordo com a verdade; verdadeiramente\">ἐπ’ ἀληθείας</span>, <strong>de acordo com a verdade, verdadeiramente</strong> (Demóstenes 18, 17; SIG 495, 174 [séc. III a.C.]; PAmh 68, 33; POxy 480, 9; Jó, Daniel; Fílon, <em>Leg. ad Gai.</em> 60; 248): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διδάσκειν\" data-meanings=\"ensinar\">διδάσκειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20.21</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰπεῖν\" data-meanings=\"dizer\">εἰπεῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.32</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λέγειν\" data-meanings=\"dizer\">λέγειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4.25</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"συνάγεσθαι\" data-meanings=\"reunir-se\">συνάγεσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 4.27</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καταλαμβάνεσθαι\" data-meanings=\"compreender; perceber\">καταλαμβάνεσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">10.34</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τελειοῦν\" data-meanings=\"completar; cumprir\">τελειοῦν</span>, 1 Cl 23:5; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπιστέλλειν\" data-meanings=\"escrever; enviar por carta\">ἐπιστέλλειν</span>, 47:3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπ’ ἀληθείας καὶ οὗτος μετ’ αὐτοῦ ἦν\" data-meanings=\"certamente também este estava com ele\">ἐπ’ ἀ. καὶ οὗτος μετ’ αὐτοῦ ἦν</span>, <strong>certamente também este estava com ele</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.59</a>. — G. Storz, <em>Gebr. u. Bedeutungsentwicklg v. ἀλήθεια u. begriffsverwandten Wörtern</em>, diss. Tübingen 1922; W. Luther, <em>‘Wahrheit’ u. ‘Lüge’ im ältest. Griechentum</em>, 1935; H. Braun, <em>Qumran und d. NT</em> II, 1966, 118–144; I. de la Potterie, TU 73, 1959, 277–294 (João); B. Jackayya, CTM 41, 1970, 171–175 (João); R. Bultmann, <em>Untersuchungen z. J. Ἀλήθεια</em>: ZNW 27, 1928, 113–163. — EDNT. M-M. TW. Spicq. Sv.</p>\n</section></article><article id=\"entry-aletheuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀληθεύω</h1><div class=\"entry-meta\"><span class=\"greek\">fut. 3 sg. ἀληθεύσει; 1 aor. impv. ἀλήθευσον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦alētheúō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro 3ª sg. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθεύσει\" data-meanings=\"será verdadeiro; dirá a verdade\">ἀληθεύσει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.34.4\" target=\"_blank\" rel=\"noopener noreferrer\">Sir 34.4</a>; 1º aor. impv. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθευσον\" data-meanings=\"dize a verdade; sê verdadeiro\">ἀλήθευσον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.20.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 20.16</a> (pré-socráticos, Ésquilo+; Pfuhl-Möbius I, 69, 3 [séc. IV a.C.]: veja New Docs 4, 145; POxy 2342, 12; PAmh 142, 1; LXX; Jos., <em>C. Ap.</em> 1, 223; Justino; Taciano 31, 4; Atenágoras, <em>R.</em> 50, 13). <strong>Ser verdadeiro, dizer a verdade</strong>; com dativo, <strong>a alguém</strong> (Fílon, <em>Cher.</em> 15), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4.16</a>. Absolutamente (Sólon: Vorsokr. 10 Fgm. 3 β 6 [= Stob. III p. 114, 10 H.]; Filóstrato, <em>Vi. Apoll.</em> 4, 16 p. 135, 2; 8, 26 p. 339, 27; Jos., <em>Bell.</em> 3, 322; <em>Vi.</em> 132): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθεύοντες ἐν ἀγάπῃ\" data-meanings=\"sendo verdadeiros / dizendo a verdade em amor\">ἀληθεύοντες ἐν ἀγάπῃ</span>, isto é, <strong>de modo que se mantenha o espírito de amor</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.15</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 21.3</a>). — M-M. TW. Spicq.</p>\n</section></article><article id=\"entry-alethes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀληθής</h1><div class=\"entry-meta\"><span class=\"greek\">ές</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦alēthḗs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Homero+.) <strong>Verdadeiro.</strong> <span class=\"sense-number\">1.</span> <strong>Relativo a ser veraz e honesto: veraz, justo, honesto</strong>, de pessoas (Ésquilo, Tucídides; IG XIV, 1071, 8; BGU 1024 VI, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2ES.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Esd 17.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 1.6</a>; Jos., <em>Ant.</em> 8, 234): de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7.18</a>. De Deus (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 15.1</a>; Fílon, <em>Spec. Leg.</em> 1, 36; Jos., <em>Bell.</em> 7, 323; SibOr Fgm. 1, 10; 5, 499): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.33\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3.33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">7.28</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">8.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.4</a>; Dg 8:8. Em geral, em oposição a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πλάνοι\" data-meanings=\"enganadores; impostores\">πλάνοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6.8</a>. De supervisores e assistentes, D 15:1.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Relativo a estar de acordo com os fatos, verdadeiro</strong>, de coisas, especialmente daquilo que é falado: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ῥῆμα\" data-meanings=\"palavra; declaração\">ῥῆμα</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.41.32\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 41.32</a>; ParJer 2:9; 3:3), Hm 3:3s.; 11:3. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παροιμία\" data-meanings=\"provérbio; dito\">παροιμία</span> (Sófocles, <em>Ajax</em> 664), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2.22</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λόγος\" data-meanings=\"palavra; declaração\">λόγος</span> (Píndaro, <em>O.</em> 1, 28; Galeno, <em>In Hippocratis De Natura Hom.</em> 29 p. 17, 26s. Mewaldt; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 13.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDT.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jdt 11.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 2.17</a>; Fílon; Just., <em>A I</em> 3, 1), Dg 12:7. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"(τὰ) ἀληθῆ λέγειν\" data-meanings=\"dizer coisas verdadeiras; dizer a verdade\">(τὰ) ἀληθῆ λέγειν</span>, <strong>dizer a verdade</strong> (Sófocles, <em>Ph.</em> 345; Ps.-Demóstenes 7, 43; POxy 37, 12 [séc. I d.C.]; PStras 41, 18 [c. 250 d.C.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">3Mac 7.12</a>; Jos., <em>Vi.</em> 286; Just., <em>A II</em> 3, 5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19.35</a>; GJs 15:4; 23:2. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοῦτο ἀληθὲς εἴρηκας\" data-meanings=\"disseste isto verdadeiramente\">τοῦτο ἀληθὲς</span> (v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθῶς\" data-meanings=\"verdadeiramente\">ἀληθῶς</span>) <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἴρηκας\" data-meanings=\"disseste\">εἴρηκας</span>, <strong>disseste isto verdadeiramente</strong> (literalmente, “como algo verdadeiro”; compare Platão; Ps.-Demóstenes 59, 34 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ταῦτ’ ἀληθῆ λέγω\" data-meanings=\"digo estas coisas verdadeiras\">ταῦτ’ ἀληθῆ λέγω</span>; Luciano, <em>Fugit.</em> 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.18</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">10.41</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πάντα ὅσα … ἀληθῆ\" data-meanings=\"tudo quanto … verdadeiro\">πάντα ὅσα … ἀλ.</span>, como Jos., <em>Ant.</em> 8, 242). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐδὲν ἀληθές\" data-meanings=\"nada verdadeiro\">οὐδὲν ἀληθές</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 14.19</a> v.l. (Enomau, o Cínico, em Eus., <em>PE</em> 5, 26, 4, diz que nos oráculos há <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μηδὲν ἀληθὲς ἢ ἔνθεον\" data-meanings=\"nada verdadeiro ou inspirado\">μηδὲν ἀληθὲς ἢ ἔνθεον</span>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τἀληθῆ διδάσκειν\" data-meanings=\"ensinar as coisas verdadeiras\">τἀληθῆ διδάσκειν</span>, Papias (2:3). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γραφαί\" data-meanings=\"escritos; Escrituras\">γραφαί</span>, 1 Cl 45:2. <strong>Confiável</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μαρτυρία\" data-meanings=\"testemunho\">μαρτυρία</span> (PHal 1, 227 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθῆ μαρτυρεῖν\" data-meanings=\"dar testemunho verdadeiro\">ἀληθῆ μαρτυρεῖν</span>; Jos., <em>Ant.</em> 4, 219 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μαρτυρία\" data-meanings=\"testemunho\">μαρτυρία</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.31\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.31s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">8.13s.</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">21.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">3Jo 12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1.13</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κρίσις\" data-meanings=\"juízo; julgamento\">κρίσις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.16</a> v.l.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γνῶσις\" data-meanings=\"conhecimento\">γνῶσις</span>, Dg 12:6. Como pergunta, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοῦτο ἀληθές;\" data-meanings=\"isto é verdade?\">τοῦτο ἀληθές;</span>, GJs 19:1, não nos papiros. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅσα ἐστὶν ἀληθῆ\" data-meanings=\"tudo o que é verdadeiro\">ὅσα ἐστὶν ἀληθῆ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4.8</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθές ἐστιν καὶ οὐκ ἔστιν ψεῦδος\" data-meanings=\"é verdadeiro e não é mentira\">ἀληθές ἐστιν καὶ οὐκ ἔστιν ψεῦδος</span> (o contraste como Platão, <em>Ep.</em> 7 p. 344b; Fílon, <em>Rer. Div. Her.</em> 132), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2.27</a>, compare v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">8</a>; Hv 3, 4, 3.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Relativo a ser real: real, genuíno, não imaginário</strong> (Tucídides e outros; PTebt 285, 3; 293, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 1.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 12.27</a>; Mel., <em>P.</em> 37 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῷ φύσει ἀληθεῖ\" data-meanings=\"ao que é verdadeiro por natureza\">τῷ φύσει ἀληθεῖ</span>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάπη\" data-meanings=\"amor\">ἀγάπη</span>, Pol 1:1; MPol 1:2. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"χάρις\" data-meanings=\"graça\">χάρις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 5.12</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ζωή\" data-meanings=\"vida\">ζωή</span> (Fílon, <em>Poster. Cai.</em> 45), Dg 12:4. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βρῶσις, πόσις\" data-meanings=\"comida, bebida\">βρῶσις, πόσις</span>, do corpo e do sangue de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.55\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.55</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα τὸ πνεῦμα ἀληθὲς εὑρεθῇ\" data-meanings=\"para que o espírito seja achado verdadeiro\">ἵνα τὸ πνεῦμα ἀληθὲς εὑρεθῇ</span>, Hm 3:1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθές ἐστιν τὸ γινόμενον διὰ τοῦ ἀγγέλου\" data-meanings=\"o que aconteceu por meio do anjo é uma realidade\">ἀ. ἐστιν τὸ γινόμενον διὰ τ. ἀγγέλου</span>, <strong>o que aconteceu por meio do anjo é uma realidade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 12.9</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔργα\" data-meanings=\"obras; feitos\">ἔργα</span>, Qua (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀεί\" data-meanings=\"sempre\">ἀεί</span> 1, fim). Sobre <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μαθητὴς ἀληθής\" data-meanings=\"discípulo verdadeiro\">μαθητὴς ἀ.</span>, IRo 4:2, veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθῶς\" data-meanings=\"verdadeiramente\">ἀληθῶς</span> b. — B. 1169. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λανθάνω\" data-meanings=\"escapar à percepção\">λανθάνω</span>. M-M. TW. Spicq. Sv.</p>\n</section></article>"};
